use vstd::prelude::*;

#[derive(Clone)]
struct RandomState {
    seed: u8,
}

verus! {
    fn random(state: RandomState) -> (result: f32)
        ensures
            0.0 <= result < 1.0,
    {
        let seed_mod = state.seed % 8; // Calculate seed modulo 8
        let result: f32 = match seed_mod {
            0 => 0.0,
            1 => 0.125,
            2 => 0.25,
            3 => 0.375,
            4 => 0.5,
            5 => 0.625,
            6 => 0.75,
            7 => 0.875,
            _ => unreachable!(), // This case will never happen
        };

        // Assert that the result is within the specified range
        assert(0.0 <= result && result < 1.0);
        result
    }
}
